
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_qtp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_qtp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.107178054789343e+00, -4.024871794890679e+00, -3.909577375819537e+00, -3.749938488112941e+00, -3.532549532067808e+00, -3.243470345479107e+00, -2.871764598897778e+00, -2.415624279681047e+00, -1.889661742708800e+00, -1.326970453804165e+00, -7.850213482580709e-01, -4.899665113591963e-01, -4.051980465737541e-01, -2.978277015418199e-01, -1.595680465157276e-01, -4.386347822123635e-02, 1.041910052257736e-03, -8.998462248362331e-04, -7.323295999047824e-05, -1.747840104082280e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


